from lib import *
S = SS('x76')
steps = [
    step("SIGTERM 到来时,一个 3 秒的请求(SIGTERM 之前 0.5 秒发出)会怎样。什么都不设:请求正常完成,200 done after 3000 ms,客户端等了 3.0 秒;进程在 SIGTERM 之后 2.6 秒退出,退出码 143;日志里是 Commencing graceful shutdown. Waiting for active requests to complete 和 Graceful shutdown complete——Boot 4.0.8 里 server.shutdown 的默认值就是 graceful。显式写 server.shutdown=immediate:请求被直接断开,客户端 0.5 秒后收到 RemoteDisconnected,进程 0.3 秒就退出了。server.shutdown=graceful 与默认完全一样(请求 200,进程 2.5 秒后退出)。把 spring.lifecycle.timeout-per-shutdown-phase 设成 1s、比请求短:请求在约 1.5 秒时被断开(RemoteDisconnected),日志是 Graceful shutdown aborted with one or more requests still active,进程 1.1 秒退出。四种情况有共同点:SIGTERM 之后 0.3 秒新建连接 /fast 都是 ConnectionRefusedError,监听端口一开始就关了;事件顺序是 AvailabilityChangeEvent REFUSING_TRAFFIC 在先、ContextClosedEvent 到达(此时 readiness=REFUSING_TRAFFIC)、再 @PreDestroy。graceful 只保护已经进来的请求,不会让新请求继续进来。", t=tl(S(1)), mark=lidx(S(1), 'server.shutdown=immediate', '比请求短'), done=lidx(S(1), '什么都不设(默认值)', 'server.shutdown=graceful(阶段超时默认 30 秒)'), b=bars([['默认:3 秒请求客户端等待(秒)', 3, '3.0,成功'], ['immediate:客户端等待(秒)', 0.5, '0.5,被断开'], ['graceful + 1s 超时:客户端等待(秒)', 1.5, '1.5,被断开'], ['默认:进程退出用时(SIGTERM 后秒)', 2.6, '2.6'], ['immediate:进程退出用时', 0.3, '0.3']], 3, done=[0, 3], mark=[1, 2, 4]), kv=KV([['server.shutdown 默认值', 'graceful(日志里 Commencing graceful shutdown)'], ['immediate', '在途请求被断开,0.3 秒退出'], ['阶段超时比请求短', '请求被断开,日志 aborted'], ['新连接', '一收到 SIGTERM 监听端口就关了']], ['server.shutdown 默认值'])),
    step("负载均衡摘除有延迟的情形(模拟,不是真的 K8s):Pod 开始终止是 t0,负载均衡要到 t0+2.0 秒才真正停止转发,这 2 秒里客户端还在以约每 10 ms 一个的节奏发请求;再在摘除前 0.1 秒发一个 3 秒的请求;preStop 睡 S 秒等价于推迟 S 秒再发 SIGTERM。不睡:immediate 摘除前发出 149 个请求,成功 0、失败 149(ConnectionRefusedError × 148、ConnectionResetError × 1);graceful 发出 162 个,成功 0、失败 162;什么都不设(默认值)157 个,失败 157。也就是说 graceful 并没有救新请求,它们全被拒绝了。睡 3 秒:immediate 发出 122 个、全部成功,但摘除前 0.1 秒发出的 3 秒请求在 SIGTERM(t0+3 秒)时仍在途,被断开,RemoteDisconnected;graceful 发出 124 个、全部成功,那个 3 秒请求也是 200 done after 3000 ms。要做到零失败,两件事缺一不可:preStop 睡眠要比负载均衡摘除的传播时间长(这里是 2.0 秒,睡 3 秒),应用本身要 graceful。", t=tl(S(2), cur=lidx(S(2), 'immediate,preStop 睡 3 秒'), mark=lidx(S(2), 'immediate,不睡', 'graceful,不睡', '什么都不设(默认值),不睡'), done=lidx(S(2), 'graceful,preStop 睡 3 秒')), mark=lidx(S(2), 'immediate,不睡', 'graceful,不睡', '什么都不设(默认值),不睡'), done=lidx(S(2), 'graceful,preStop 睡 3 秒'), b=bars([['immediate 不睡:失败请求数', 149, '149 / 149'], ['graceful 不睡:失败请求数', 162, '162 / 162'], ['默认值 不睡:失败请求数', 157, '157 / 157'], ['immediate 睡 3 秒:失败请求数(另有 1 个在途 3 秒请求被断开)', 0, '0 / 122'], ['graceful 睡 3 秒:失败请求数', 0, '0 / 124']], 162, mark=[0, 1, 2], done=[4], cur=[3]), kv=KV([['不睡', 'graceful 也救不了新请求,端口已经关了'], ['睡 3 秒 + immediate', '新请求零失败,在途的 3 秒请求被断开'], ['睡 3 秒 + graceful', '零失败,在途请求也完成'], ['睡多久', '要大于负载均衡的摘除传播时间']], ['睡 3 秒 + graceful'])),
    step("阶段超时的默认值。一个 40 秒的请求在途,SIGTERM 之后进程等了 30.1 秒才退出,日志是 Graceful shutdown aborted with one or more requests still active,退出码 143;客户端那边是我自己设的 20 秒超时先触发了 TimeoutError,所以看到的不是服务端断开。也就是说 spring.lifecycle.timeout-per-shutdown-phase 不设的时候,最长等 30 秒;如果它比 K8s 的 terminationGracePeriodSeconds 长,进程会先被 SIGKILL(我没有在 K8s 里验证,这里只是读数字)。", t=tl(S(3)), mark=lidx(S(3), '进程在 SIGTERM 之后 30.1'), done=lidx(S(3), 'aborted', '正在处理的 /slow?ms=40000'), b=bars([['40 秒请求:SIGTERM 后进程退出用时(秒)', 30.1, '30.1'], ['客户端自己的超时(秒)', 20, '20.0']], 30.1, mark=[0], done=[1]), kv=KV([['默认等待上限', '30 秒(没设时实测 30.1 秒)'], ['超时之后', '日志 aborted,请求被断开'], ['客户端', '自己的 20 秒超时先触发'], ['和 K8s 的关系', '未验证']], ['默认等待上限'])),
]
A = mkartx('x76', 76, 'Spring,Boot,优雅停机,graceful shutdown,preStop,K8s,真实验证,动画演示',
    '实测 Spring Boot 4.0.8 的优雅停机:server.shutdown 的默认值就是 graceful,在途的 3 秒请求能完成,新连接立刻被拒绝;graceful 救不了新请求,负载均衡摘除延迟 2 秒的模拟里,不睡 149~162 个请求全部失败,preStop 睡 3 秒加上 graceful 才是零失败;阶段超时默认等 30 秒。',
    '发布时为什么还会有 502?server.shutdown=graceful 到底保护了什么?preStop 睡几秒才够?阶段超时是多少?这篇用 SIGTERM 加一个会慢的接口,再用 Python 模拟负载均衡的摘除延迟,逐项实测。',
    [('graceful 是默认值', 'Boot 4.0.8 不设 server.shutdown 时,在途请求完成,日志是 Commencing graceful shutdown'), ('149 ~ 162 / 0', '模拟负载均衡 2 秒摘除延迟:不睡时失败请求数在 149 到 162 之间;preStop 睡 3 秒 + graceful 失败 0'), ('30.1 秒', '没设 timeout-per-shutdown-phase 时,在途 40 秒请求下进程的退出用时')],
    [('SIGTERM 之后的行为', '<p>graceful 是默认值;在途请求完成,新连接立刻被拒绝;immediate 会断开在途请求;阶段超时比请求短也会断开。</p>'),
     ('摘除延迟与 preStop', '<p>graceful 只保护已经进来的请求;负载均衡还在转发时,新请求会撞上已关闭的端口;preStop 要睡得比摘除传播时间长。</p>'),
     ('阶段超时', '<p>默认最长等 30 秒,之后日志 aborted 并断开请求。</p>')],
    steps,
    [ENV_X + '。被测应用是 spring-boot-starter-webmvc(内嵌 Tomcat)的单个程序,一个 /slow?ms=N 接口;客户端是 Python http.client(超时 20 秒);SIGTERM 用 Popen.send_signal 直接发给 java 进程;第二节是模拟:负载均衡的「摘除延迟」就是让发请求的线程在 t0+2.0 秒停止,preStop 睡眠就是推迟发 SIGTERM,没有真正的 K8s、Service 或 Endpoints',
     '没有验证:真实的 K8s(Endpoints 摘除的实际传播时间、kube-proxy / Ingress 的缓存、terminationGracePeriodSeconds 与 SIGKILL 的配合);Actuator 的 readiness 探针在停机期间的表现(这里只看了 ApplicationAvailability 的状态);Jetty 等其他容器的行为;HTTP/2、WebSocket、SSE 等长连接在停机时的表现;@Async 线程池、消息消费者、定时任务的优雅停机;JDK 21 之外版本的 SIGTERM 处理'],
    '优雅停机')
